import math
pts=[(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)]
fill=set()
for i,a in enumerate(pts):
 for b in pts[i+1:]:
  dr=b[0]-a[0]; dc=b[1]-a[1]; g=math.gcd(abs(dr),abs(dc))
  for k in range(1,g): fill.add((a[0]+k*(dr//g),a[1]+k*(dc//g)))
grid=[[8]*8 for _ in range(30)]
for r,c in fill: grid[r][c]=3
for r,c in pts: grid[r][c]=7
print('overlap points',sorted(set(pts)&fill))
print('rows:')
for row in grid: print(row)

